using System;using System.IO;using System.Collections;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.Rendering;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class HandprintTimingProbe:MonoBehaviour{
 string folder;int failures;WatchDemoController w;Camera cam;RenderPipelineAsset previous;
 public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Wet handprint review").AddComponent<HandprintTimingProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 void Check(bool ok,string s){File.AppendAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+s+"\n");if(!ok)failures++;}
 void Capture(string name){var rt=new RenderTexture(1100,850,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1100,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1100,850),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;Destroy(tex);Destroy(rt);}
 IEnumerator Go(){
  w=FindAnyObjectByType<WatchDemoController>();var scene=w.GetComponent<NightmareScene>();var rig=FindAnyObjectByType<XROrigin>();foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality")||b.GetType().Name=="DesktopPreview")b.enabled=false;var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;
  HorrorTuning.Current.nightmareEnabled=true;Check(scene.Begin(true),"Nightmare started");scene.enabled=false;var c=w.State.Scare;for(int i=0;i<100&&c.Beat!=ScareBeat.Follow;i++)c.Tick(.1f,true,false,0,0);var kit=(ScareKit)typeof(NightmareScene).GetField("kit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(scene);c.Place(new Vector3(-1.5f,3.3f,-2.5f),0);kit.Beat(ScareBeat.Follow,0);int colliders=FindObjectsByType<MeshCollider>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;var timer=System.Diagnostics.Stopwatch.StartNew();kit.Present(c,rig.Camera.transform.position);timer.Stop();Check(FindObjectsByType<MeshCollider>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length==colliders,"Playback does not create or cook a mesh collider");File.AppendAllText(folder+"/checks.txt","First presentation on this Mac: "+timer.Elapsed.TotalMilliseconds.ToString("F1")+" ms (not a Quest measurement)\n");yield return null;
  var marks=FindObjectsByType<MeshFilter>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(x=>x.name.StartsWith("Wet child handprint ")).ToArray();var visible=marks.Where(x=>x.gameObject.activeInHierarchy).ToArray();Check(marks.Length==6,"Six projected rail marks were created ("+marks.Length+")");Check(visible.Length>0,"Marks become visible behind the descending child ("+visible.Length+")");Check(marks.All(x=>!x.GetComponent<Collider>()),"Decorative marks add no player colliders");
  bool projected=true;foreach(var m in marks){int segment=int.Parse(m.name.Substring(m.name.LastIndexOf(' ')+1));var rail=GameObject.Find("SM_Rail_F2_F3_Inner_Top_"+segment);var filter=rail?rail.GetComponent<MeshFilter>():null;if(!filter||!filter.sharedMesh){projected=false;continue;}var col=rail.AddComponent<MeshCollider>();col.sharedMesh=filter.sharedMesh;foreach(var v in m.sharedMesh.vertices){var pt=m.transform.TransformPoint(v);var allowed=rail.GetComponent<Renderer>().bounds;allowed.Expand(.01f);if(!allowed.Contains(pt)){projected=false;break;}if(!col.Raycast(new Ray(pt+Vector3.up*.03f,Vector3.down),out var hit,.06f)||Vector3.Distance(pt,hit.point)>.006f){projected=false;break;}}col.enabled=false;Destroy(col);}Check(projected,"Marks stay within their rail bounds and within 6 mm of its surface");
  var mark=visible.FirstOrDefault(x=>x.name.EndsWith(" 3"));if(mark){var centre=mark.GetComponent<Renderer>().bounds.center;var eye=centre+Vector3.up*.45f;rig.MoveCameraToWorldLocation(eye);rig.Camera.transform.LookAt(centre);var flash=FindObjectsByType<WatchLantern>(FindObjectsSortMode.None).First(x=>x.Slot==0);var pos=centre+Vector3.up*.30f+Vector3.right*.25f;flash.transform.SetPositionAndRotation(pos,Quaternion.LookRotation(centre-pos));var actual=flash.GetComponentInChildren<Light>(true);flash.transform.position+=pos-actual.transform.position;w.State.CycleLantern(0);yield return new WaitForSeconds(.25f);cam=new GameObject("Handprint review camera").AddComponent<Camera>();cam.enabled=false;cam.fieldOfView=48;cam.nearClipPlane=.02f;cam.transform.SetPositionAndRotation(rig.Camera.transform.position,rig.Camera.transform.rotation);previous=QualitySettings.renderPipeline;QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/_LighthouseKeepers/Settings/RenderPipeline/QuestPipeline.asset");yield return new WaitForSeconds(.3f);Capture("wet-handprint");Check(actual.enabled&&Vector3.Dot(actual.transform.forward,(centre-actual.transform.position).normalized)>.99f,"Actual flashlight was aimed at the rail for the capture");QualitySettings.renderPipeline=previous;Destroy(cam.gameObject);}
  File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");Destroy(gameObject);
 }
}
